import subprocess,re
files=subprocess.run(['git','ls-files'],capture_output=True,text=True).stdout.split('\n')
files=[f for f in files if f and not f.endswith('.png')]
def norm(t): return re.findall(r"[a-z0-9']+", t.lower())
def shingles(words,n=7): return {' '.join(words[i:i+n]) for i in range(len(words)-n+1)}
src={}
src['LICENSE']=open('LICENSE',encoding='utf-8').read()
src['LICENSE-CODE']=open('LICENSE-CODE',encoding='utf-8').read()
t=open('THIRD-PARTY-NOTICES.md',encoding='utf-8').read().split('\n')
src['APACHE']='\n'.join(t[63:241])
m=open('rounds/00-initial/responses/mistral-small-3-2-24b.md',encoding='utf-8').read().split('\n')
src['MISTRAL']='\n'.join(m[74:101])
S={k:shingles(norm(v)) for k,v in src.items()}
for f in files:
    try: txt=open(f,encoding='utf-8').read()
    except Exception: continue
    lines=txt.split('\n')
    for k,sh in S.items():
        if (k=='LICENSE' and f=='LICENSE') or (k=='LICENSE-CODE' and f=='LICENSE-CODE'): continue
        hits=[]
        for i,l in enumerate(lines):
            w=norm(l)
            # window over line + next line
            w=norm(l+' '+(lines[i+1] if i+1<len(lines) else ''))
            if shingles(w)&sh: hits.append(i+1)
        if hits:
            if k=='APACHE' and f=='THIRD-PARTY-NOTICES.md': 
                hits=[h for h in hits if h<63 or h>241]
            if k=='MISTRAL' and f=='rounds/00-initial/responses/mistral-small-3-2-24b.md':
                hits=[h for h in hits if h<74 or h>101]
            if hits: print(k,f,hits[:15],len(hits))
